params.command:
cd phase2/extraterrestrial && python extraterrestrial_engine.py && echo "=== NEW CLAIMS ===" && python -c "
import extraterrestrial_engine as e
r=e.analyze()
for c in r['claims'][-3:]: print(' *',c,'\n')
print('NEW EVIDENCE KINDS:', [x['kind'] for x in r['evidence'] if 'q1' in x['kind'] or 'q2' in x['kind']])
p=r['evidence'][[x['kind'] for x in r['evidence']].index('q1_power_analysis')]['value']
for k,v in p.items(): print('  %-52s %s'%(k,v))
n=r['evidence'][[x['kind'] for x in r['evidence']].index('q2_null_survey_power')]['value']
for k,v in n.items(): print('  %-52s %s'%(k,v))
"

